export { anatomy, type ProgressPart, parts } from "./progress.anatomy";
export { connect } from "./progress.connect";
export { getLabelId, getRootId, getValueTextId } from "./progress.dom";
export { machine } from "./progress.machine";
export type {
  ProgressApi,
  ProgressMachineProps,
  ProgressSchema,
  ProgressState,
  ProgressValueChangeDetails,
  ResolvedProgressMachineProps,
} from "./progress.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type ProgressPart =
  | "root"
  | "label"
  | "track"
  | "range"
  | "valueText"
  | "circle"
  | "circleTrack"
  | "circleRange";

export const anatomy: Anatomy<ProgressPart> = createAnatomy("progress").parts(
  "root",
  "label",
  "track",
  "range",
  "valueText",
  "circle",
  "circleTrack",
  "circleRange",
);

export const parts: Record<ProgressPart, AnatomyPart> = anatomy.build();

/**
 * The circle's geometry is fixed here rather than made configurable: a viewBox of
 * 100 × 100 with r = 42 leaves room for the thickest stroke the design system
 * asks for, and the SVG scales to whatever size the CSS gives it. A `size` prop
 * would only be a second way to say `inline-size`.
 */

import { dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./progress.anatomy";
import { getLabelId, getRootId, getValueTextId } from "./progress.dom";
import type { ProgressApi, ProgressSchema } from "./progress.types";

const RADIUS = 42;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

export function connect<T extends PropTypes>(
  service: Service<ProgressSchema>,
  normalize: NormalizeProps<T>,
): ProgressApi<T> {
  const { context, prop, computed, send, scope } = service;

  const value = context.get("value");
  const percent = computed("percent");
  const state = computed("state");
  const indeterminate = state === "indeterminate";
  const orientation = prop("orientation");

  const stateAttrs = {
    "data-state": state,
    "data-orientation": orientation,
  };

  return {
    value,
    percent,
    indeterminate,
    complete: state === "complete",
    valueAsText: computed("valueAsText"),

    setValue(next: number | null): void {
      send({ type: "VALUE.SET", value: next });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        role: "progressbar",
        dir: prop("dir"),
        // Only when the label part is really there: a bar pointing at a label
        // that was never rendered has no accessible name, which is worse than
        // having none declared — a consumer's own `aria-label` cannot win
        // against a dangling IDREF.
        "aria-labelledby": context.get("hasLabel") ? getLabelId(scope) : undefined,
        // Dropped, not zeroed: an indeterminate bar that reports 0 is a bar that
        // says the work has not started.
        "aria-valuemin": indeterminate ? undefined : prop("min"),
        "aria-valuemax": indeterminate ? undefined : prop("max"),
        "aria-valuenow": indeterminate || value === null ? undefined : value,
        "aria-valuetext": indeterminate ? undefined : computed("valueAsText"),
        "data-indeterminate": dataAttr(indeterminate),
        style: { "--sui-progress-percent": percent === null ? "0%" : `${percent}%` },
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, ...stateAttrs, id: getLabelId(scope) }),

    getTrackProps: (): T["element"] => normalize.element({ ...parts.track.attrs, ...stateAttrs }),

    getRangeProps: (): T["element"] =>
      normalize.element({
        ...parts.range.attrs,
        ...stateAttrs,
        "data-indeterminate": dataAttr(indeterminate),
      }),

    getValueTextProps: (): T["element"] =>
      normalize.element({
        ...parts.valueText.attrs,
        ...stateAttrs,
        id: getValueTextId(scope),
        // The root already publishes the value to assistive technology through
        // `aria-valuetext`; reading the same number twice helps nobody.
        "aria-hidden": "true",
      }),

    getCircleProps: (): T["svg"] =>
      normalize.svg({
        ...parts.circle.attrs,
        ...stateAttrs,
        viewBox: "0 0 100 100",
        focusable: false,
        "aria-hidden": "true",
      }),

    getCircleTrackProps: (): T["circle"] =>
      normalize.circle({ ...parts.circleTrack.attrs, cx: 50, cy: 50, r: RADIUS, fill: "none" }),

    getCircleRangeProps: (): T["circle"] =>
      normalize.circle({
        ...parts.circleRange.attrs,
        ...stateAttrs,
        cx: 50,
        cy: 50,
        r: RADIUS,
        fill: "none",
        strokeLinecap: "round",
        strokeDasharray: CIRCUMFERENCE,
        // A quarter arc while indeterminate, spun by CSS: the geometry says
        // "unknown amount of work", the animation says "still working".
        strokeDashoffset:
          percent === null ? CIRCUMFERENCE * 0.75 : CIRCUMFERENCE * (1 - percent / 100),
        "data-indeterminate": dataAttr(indeterminate),
      }),
  };
}

import { query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "progress";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getValueTextId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "valueText");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * `aria-labelledby` may only point at an id that exists. A bar rendered without
 * the optional label part — the commonest way one ships — would otherwise have
 * no accessible name at all, and axe is right to call that a violation.
 */
export function hasLabel(scope: Scope): boolean {
  return query(getRootEl(scope), '[data-part~="progress:label"]') !== null;
}

/**
 * One state, and that is not an oversight: a progress bar has no interaction
 * modes to model. What it does have is a value that can be controlled or not, a
 * range to clamp against, and ids to derive for its label — which is exactly what
 * a service provides and a bare prop getter would have to reinvent.
 *
 * `null` is indeterminate, and it is a value rather than the absence of one. That
 * distinction is what lets `aria-valuenow` be dropped deliberately instead of by
 * accident, which is the difference between "still working" and "0%".
 */

import { observeChildren } from "../../dom/observers";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getRootEl, hasLabel } from "./progress.dom";
import type { ProgressSchema, ProgressState } from "./progress.types";

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export const machine: Machine<ProgressSchema> = createMachine<ProgressSchema>({
  props({ props }) {
    return {
      min: 0,
      max: 100,
      orientation: "horizontal",
      locale: "en-US",
      formatOptions: { style: "percent" },
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<number | null>(() => ({
        // `?? null` would turn an explicit `defaultValue: null` into 0 on the way
        // back out; the coalescing has to be on absence, not on nullishness.
        defaultValue: prop("defaultValue") === undefined ? 0 : prop("defaultValue"),
        value: prop("value"),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "progress value",
      })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    percent({ context, prop }) {
      const value = context.get("value");
      if (value === null) return null;
      const min = prop("min");
      const max = prop("max");
      if (max <= min) return 100;
      return ((clamp(value, min, max) - min) / (max - min)) * 100;
    },

    state({ context, prop }): ProgressState {
      const value = context.get("value");
      if (value === null) return "indeterminate";
      return value >= prop("max") ? "complete" : "loading";
    },

    valueAsText({ computed, context, prop }) {
      const percent = computed("percent");
      const value = context.get("value");
      if (percent === null || value === null) return "";
      const options = prop("formatOptions");
      // A percentage is the *progress*, expressed as the fraction Intl expects.
      // Anything else formats the value itself: "3 MB of 7" is the number 3, not
      // the 43 % it happens to represent.
      const isPercent = options.style === "percent";
      return new Intl.NumberFormat(prop("locale"), options).format(
        isPercent ? percent / 100 : value,
      );
    },
  },

  initialState() {
    return "idle";
  },

  effects: ["trackParts"],

  watch({ scope, track, action }) {
    track(
      () => [hasLabel(scope)],
      () => action(["syncParts"]),
    );
  },

  on: {
    "VALUE.SET": { actions: ["setValue"] },
    "PARTS.SYNC": { actions: ["syncParts"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    actions: {
      setValue({ context, event, prop }) {
        if (event.type !== "VALUE.SET") return;
        const next = event.value;
        context.set("value", next === null ? null : clamp(next, prop("min"), prop("max")));
      },
      syncParts({ context, scope }) {
        context.set("hasLabel", hasLabel(scope));
      },
    },

    effects: {
      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        return observeChildren(getRootEl(scope), () => send({ type: "PARTS.SYNC" }));
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, Orientation } from "../../types";

export interface ProgressValueChangeDetails {
  readonly value: number | null;
}

export type ProgressState = "indeterminate" | "loading" | "complete";

export interface ProgressMachineProps {
  readonly dir?: Direction | undefined;
  /** `null` is indeterminate — a real value, not a missing one. Controlled. */
  readonly value?: number | null | undefined;
  readonly defaultValue?: number | null | undefined;
  readonly min?: number | undefined;
  readonly max?: number | undefined;
  readonly orientation?: Orientation | undefined;
  readonly locale?: string | undefined;
  /** Passed to `Intl.NumberFormat` for the value text. Percent by default. */
  readonly formatOptions?: Intl.NumberFormatOptions | undefined;
  readonly onValueChange?: ((details: ProgressValueChangeDetails) => void) | undefined;
}

export interface ResolvedProgressMachineProps extends ProgressMachineProps {
  readonly min: number;
  readonly max: number;
  readonly orientation: Orientation;
  readonly locale: string;
  readonly formatOptions: Intl.NumberFormatOptions;
}

export interface ProgressSchema extends MachineSchema {
  state: "idle";
  props: ResolvedProgressMachineProps;
  context: { value: number | null; hasLabel: boolean };
  computed: { percent: number | null; state: ProgressState; valueAsText: string };
  event: { type: "VALUE.SET"; value: number | null } | { type: "PARTS.SYNC" };
  action: "setValue" | "syncParts";
  effect: "trackParts";
}

export interface ProgressApi<T extends PropTypes = PropTypes> {
  readonly value: number | null;
  /** `null` while indeterminate, so a consumer cannot render "0%" by accident. */
  readonly percent: number | null;
  readonly indeterminate: boolean;
  readonly complete: boolean;
  readonly valueAsText: string;
  setValue(value: number | null): void;
  getRootProps(): T["element"];
  getLabelProps(): T["element"];
  getTrackProps(): T["element"];
  getRangeProps(): T["element"];
  getValueTextProps(): T["element"];
  getCircleProps(): T["svg"];
  getCircleTrackProps(): T["circle"];
  getCircleRangeProps(): T["circle"];
}

export type {
  ProgressMachineProps,
  ProgressState,
  ProgressValueChangeDetails,
} from "@standarui/core/progress";
export {
  Progress,
  type ProgressComposedProps,
  type ProgressParts,
} from "./composed";
export {
  type ProgressApi,
  ProgressCircle,
  ProgressCircleRange,
  ProgressCircleTrack,
  ProgressLabel,
  ProgressRange,
  ProgressRoot,
  type ProgressRootProps,
  ProgressTrack,
  ProgressValueText,
  type UseProgressProps,
  useProgress,
} from "./progress";

import * as progress from "@standarui/core/progress";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type ProgressApi = progress.ProgressApi<ReactPropTypes>;

const ProgressContext = createPartContext<ProgressApi>("Progress");

export interface UseProgressProps extends progress.ProgressMachineProps, MachineRuntimeProps {}

export function useProgress(props: UseProgressProps): ProgressApi {
  return progress.connect(useMachine(progress.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "value",
  "defaultValue",
  "min",
  "max",
  "orientation",
  "locale",
  "formatOptions",
  "onValueChange",
] as const;

export interface ProgressRootProps extends UseProgressProps, PartProps<"div", UseProgressProps> {}

export function ProgressRoot(props: ProgressRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useProgress(machineProps);

  return (
    <ProgressContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </ProgressContext.Provider>
  );
}

export const ProgressLabel: (props: PartProps<"span">) => ReactNode = createPart(ProgressContext, {
  name: "ProgressLabel",
  element: "span",
  props: (api) => api.getLabelProps(),
});

export const ProgressTrack: (props: PartProps<"div">) => ReactNode = createPart(ProgressContext, {
  name: "ProgressTrack",
  element: "div",
  props: (api) => api.getTrackProps(),
});

export const ProgressRange: (props: PartProps<"div">) => ReactNode = createPart(ProgressContext, {
  name: "ProgressRange",
  element: "div",
  props: (api) => api.getRangeProps(),
});

export const ProgressValueText: (props: PartProps<"span">) => ReactNode = createPart(
  ProgressContext,
  {
    name: "ProgressValueText",
    element: "span",
    props: (api) => api.getValueTextProps(),
  },
);

export const ProgressCircle: (props: PartProps<"svg">) => ReactNode = createPart(ProgressContext, {
  name: "ProgressCircle",
  element: "svg",
  props: (api) => api.getCircleProps(),
});

export const ProgressCircleTrack: (props: PartProps<"circle">) => ReactNode = createPart(
  ProgressContext,
  {
    name: "ProgressCircleTrack",
    element: "circle",
    props: (api) => api.getCircleTrackProps(),
  },
);

export const ProgressCircleRange: (props: PartProps<"circle">) => ReactNode = createPart(
  ProgressContext,
  {
    name: "ProgressCircleRange",
    element: "circle",
    props: (api) => api.getCircleRangeProps(),
  },
);
